    "cart",
    "fav",
    "buy"
  ],
  "primary": "Validation is_click ROC-AUC. All four AUC/Logloss values and mean AUC are reported; auxiliary mean is not the selection score.",
  "optional": [
    "Literal CONFIG dict for model architecture only; all frozen host parameters are rejected.",
