/bin/bash -lc "python3 - <<'PY'
import json,subprocess
c=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))['context']
for k,v in c.items():
 if k=='history':
  print('HISTORY')
  for t in v:
   print(json.dumps({a:t.get(a) for a in ['id','parent','status','wall_seconds','parameters','dense_parameters','error','note']}),json.dumps({'auc':t.get('validation',{}).get('auc'),'config':t.get('config')}))
 elif k=='trajectory_index': print(k,json.dumps(v,indent=2))
 else: print(k,json.dumps(v,indent=2))
PY"

