import ast,copy,hashlib,json,subprocess
from pathlib import Path
root=Path('/workspace');p=json.loads((root/'proposal.json').read_text());r=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001']));w=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','workspace://w-001']))
def validate(x,s,path='"'$'"'):
 t=s.get('type')
 if t:
  types={'object':dict,'array':list,'string':str,'boolean':bool}
  assert isinstance(x,types[t]),(path,t)
 if 'const' in s:assert x==s['const'],path
 if 'enum' in s:assert x in s['enum'],path
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+'['+str(i)+']')
 if isinstance(x,dict):
  for k in s.get('required',[]):assert k in x,(path,k)
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),path
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
ids=set(r['context']['allowed_observation_ids']);assert p['parent_trial'] in ids;assert set(p['study']['evidence_refs'])<=ids
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants']);assert len({v['file'] for v in p['variants']})==len(p['variants'])
def cl(t):return next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
def methods(t):return {n.name:n for n in cl(t).body if isinstance(n,ast.FunctionDef)}
ancestor=ast.parse((root/'history_g0_r0054_outside_transfer_bridge.py').read_text());ancestor_methods=methods(ancestor)
normalized=[]
for v in p['variants']:
 f=root/v['file'];assert f.parent==root and f.suffix=='.py';t=ast.parse(f.read_text());compile(t,str(f),'exec');m=methods(t)
 config=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(z,ast.Name) and z.id=='CONFIG' for z in n.targets));assert config==v['config']
 init=m['__init__'];defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,value in config.items():
  default=defaults[k];default=list(default) if isinstance(default,tuple) else default
  assert default==value,(f.name,k,default,value)
 for name,node in ancestor_methods.items():
  if name not in ['__init__','_context_history_correction']:assert ast.dump(m[name])==ast.dump(node),(f.name,name)
 def nn_calls(node):return [ast.dump(z) for z in ast.walk(node) if isinstance(z,ast.Call) and isinstance(z.func,ast.Attribute) and isinstance(z.func.value,ast.Name) and z.func.value.id=='nn']
 assert nn_calls(init)==nn_calls(ancestor_methods['__init__']),f.name
 for node in ast.walk(t):
  if isinstance(node,ast.Import):assert all(n.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for n in node.names)
  if isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in {'open','eval','exec','compile','__import__','input'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Attribute):assert node.func.attr not in {'load','save','load_state_dict','set_grad_enabled','backward'}
 z=copy.deepcopy(t)
 for node in z.body:
  if isinstance(node,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in node.targets):node.value=ast.Constant(None)
 zi=methods(z)['__init__'];ix=[a.arg for a in zi.args.args].index('pair_statistic')-(len(zi.args.args)-len(zi.args.defaults));zi.args.defaults[ix]=ast.Constant(None)
 normalized.append(ast.dump(z))
 print(f.name,'syntax/config/defaults/imports/inherited-methods/module-construction PASS','sha256',hashlib.sha256(f.read_bytes()).hexdigest())
assert len(set(normalized))==1
for source in w['available_ancestor_sources']:
 assert hashlib.sha256((root/source['file']).read_bytes()).hexdigest()==source['source_sha256'],source['file']
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print('Study schema, authorized protocol/evidence/lineage, four-cell AST parity, seven ancestor and baseline digests PASS. No native tensor execution.')
PY"

